// Use the actually compiled immutable GutTS runtime implementation; do not
// substitute handwritten JavaScript arithmetic or precomputed mock outcomes.
// The source under dist/ is generated by tsc from the pinned TypeScript commit.
import {spawnSync} from 'node:child_process';
import {readFileSync, writeFileSync} from 'node:fs';
import {resolve,join} from 'node:path';
import {pathToFileURL} from 'node:url';

if(process.argv.length!==4){
  console.error('Usage: node scripts/verify-minilm-cosine.mjs <pinned-GutTS-root> <C++-runner>');
  process.exit(2);
}
const root=resolve(process.argv[2]);
const runner=resolve(process.argv[3]);
const sourcePath=join(root,'dist/models/runtimes/transformers.js');
const source=readFileSync(sourcePath,'utf8');
if(!source.includes('function cosine('))throw new Error('Pinned GutTS MiniLM cosine implementation unavailable');
// Append a test-only export to the generated compiled module. Do not edit the
// upstream TypeScript source or any tracked repository file.
const testPath=join(root,'dist/models/runtimes/transformers-gutcpp-cosine-test.js');
writeFileSync(testPath,source+'\nexport { cosine };\n');
const {cosine}=await import(pathToFileURL(testPath).href);
if(typeof cosine!=='function')throw new Error('Actual compiled GutTS cosine not exportable');
const vectors=[
  {left:[1,0],right:[0,1]},
  {left:[1,1],right:[1,1]},
  {left:[1,1],right:[-1,-1]},
  {left:[0,0],right:[1,1]},
  {left:[],right:[]},
  {left:[1,2],right:[1]},
  {left:[1],right:[1,100]},
  {left:[0.2,0.5],right:[-0.2,0.4]},
  {left:[1e-4,2e-4],right:[3e-4,4e-4]},
  {left:[3,4,5],right:[6,7,8]},
  {left:[1,-2,3,-4],right:[-3,4,-5,6]},
  {left:[1e20,1e20],right:[-1e20,1e20]},
  {left:[1e-30,-1e-30],right:[1e-30,1e-30]},
  {left:[10],right:[-10]},
  {left:[0.33333333333,0.6666666666],right:[0.1,0.9]},
  {left:[1,2,3],right:[]},
];
for(let i=0;i<16;i++){
 const left=Array.from({length:5},(_,j)=>((i*31+j*17)%37-18)/11);
 const right=Array.from({length:5},(_,j)=>((i*17+j*23)%41-20)/9);
 vectors.push({left,right});
}
const cases=vectors.map(({left,right})=>({kind:'cosine',left,right}));
for(const {left,right} of vectors.filter(x=>x.left.length===x.right.length&&x.left.length>0)){
 cases.push({kind:'pooled',pooled:[...left,...right]});
}
cases.push({kind:'pooled',pooled:[]},{kind:'pooled',pooled:[1,2,3]});
const payload=cases.map(x=>JSON.stringify(x)).join('\n')+'\n';
const child=spawnSync(runner,[],{input:payload,encoding:'utf8',maxBuffer:8*1024*1024,timeout:30000});
if(child.status!==0)throw new Error(`MiniLM C++ runner failed: ${child.stderr||child.status}`);
const lines=child.stdout.trim().split('\n');
if(lines.length!==cases.length)throw new Error(`MiniLM C++ result count mismatch ${lines.length}/${cases.length}`);
function classify(value){
 if(Number.isNaN(value))return {ok:true,kind:'nan'};
 if(value===Infinity)return {ok:true,kind:'pos_inf'};
 if(value===-Infinity)return {ok:true,kind:'neg_inf'};
 return {ok:true,kind:'finite',value};
}
let matches=0;
for(let i=0;i<cases.length;i++){
 const testcase=cases[i];
 let expected;
 try{
  const left=testcase.kind==='cosine'?testcase.left:testcase.pooled.slice(0,testcase.pooled.length/2);
  const right=testcase.kind==='cosine'?testcase.right:testcase.pooled.slice(testcase.pooled.length/2);
  if(testcase.kind==='pooled'&&(testcase.pooled.length<2||testcase.pooled.length%2!==0))throw new Error('Invalid model tensor');
  expected=classify(cosine(new Float32Array(left),new Float32Array(right)));
 }catch{expected={ok:false,kind:'error'};}
 const actual=JSON.parse(lines[i]);
 const same=expected.ok===actual.ok&&expected.kind===actual.kind&&
   (expected.kind!=='finite'||Math.abs(actual.value-expected.value)<=2e-10*Math.max(1,Math.abs(expected.value)));
 if(!same){console.error({index:i,testcase,expected,actual});process.exitCode=1;}
 else matches++;
}
console.log(`Pinned compiled GutTS MiniLM cosine vs C++17: ${matches}/${cases.length} matching real numerical cases`);
if(matches!==cases.length)process.exitCode=1;
